  function bookingNoticeView(){
    const n=state.bookingNotices,items=Array.isArray(n?.items)?n.items:[],reminders=(n?.reminders||[]).filter(b=>Date.parse(b.starts_at)>Date.now()&&Date.parse(b.starts_at)<=Date.now()+86400000).sort((a,b)=>Date.parse(a.starts_at)-Date.parse(b.starts_at)),unread=Number(n?.unread)||0,filter=state.noticeFilter||'all';
    const rows=items.filter(x=>filter==='all'||!x.read_at).sort((a,b)=>Number(Boolean(a.read_at))-Number(Boolean(b.read_at))||Date.parse(b.created_at||b.starts_at)-Date.parse(a.created_at||a.starts_at));
    return `<div class="page-head"><div><span class="label">GOODDINER · NOTIFICHE</span><h1>Notifiche e promemoria</h1><p>Controlla gli aggiornamenti qui. Non vengono inviate notifiche push.</p></div>${button('Aggiorna','booking-notices','btn-outline')}</div>${!n?notice('Notifiche non ancora caricate. Premi Aggiorna.'):`<section class="card stack"><h2>Prossime 24 ore</h2>${reminders.length?reminders.map(b=>`<article class="item"><div class="item-main"><strong>${e(b.restaurant_name)}</strong><small>${e(bookingDate(b.starts_at))} · ${Number(b.party)} persone</small></div>${state.side==='customer'?button('Calendario','booking-calendar','btn-outline','data-id="'+e(b.id)+'"'):''}</article>`).join(''):empty('Nessun promemoria','Le prossime prenotazioni compariranno qui.')}</section><section class="card stack"><div class="row between"><h2>Aggiornamenti</h2><span class="pill">${unread} non lette</span></div><div class="booking-actions">${button('Tutte','notice-filter','btn-'+(filter==='all'?'dark':'outline'),'data-id="all"')}${button('Non lette','notice-filter','btn-'+(filter==='unread'?'dark':'outline'),'data-id="unread"')}</div>${unread?button('Segna tutte come lette','booking-notices-read','btn-outline'):''}${rows.length?rows.map(x=>`<article class="item"><div class="item-main"><strong>${e(bookingStatuses[x.kind]||x.kind)} · ${e(x.restaurant_name)}</strong><small>${e(bookingDate(x.starts_at))} · ${Number(x.party)} persone</small></div>${x.read_at?'':'<span class="pill pill-warm">Nuova</span>'}</article>`).join(''):empty('Nessuna notifica','Non ci sono aggiornamenti per questo filtro.')}</section>`}`;
  }
  function calendarDownload(b){const clean=x=>String(x||'').replace(/[\\;,\r\n]/g,c=>c==='\r'?'':c==='\n'?'\\n':'\\'+c);const iso=x=>new Date(x).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const body=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//GoodDiner//Booking//IT','BEGIN:VEVENT','UID:'+b.id+'@gooddiner','DTSTAMP:'+iso(Date.now()),'DTSTART:'+iso(b.starts_at),'SUMMARY:'+clean('GoodDiner · '+b.restaurant_name),'DESCRIPTION:'+clean(b.party+' persone. Verifica lo stato della prenotazione in GoodDiner.'),'BEGIN:VALARM','TRIGGER:-PT2H','ACTION:DISPLAY','DESCRIPTION:Promemoria prenotazione GoodDiner','END:VALARM','END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([body],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='gooddiner-prenotazione.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function agendaRows(){return state.bookings.filter(b=>!state.bookingAgendaDay||romeDay(new Date(b.starts_at))===state.bookingAgendaDay);}
  // Server-side booking disclosure is not yet installed or approved.
  function canShowBookingProfile(b){return Boolean(b&&b.source==='online'&&['pending','confirmed'].includes(b.status)&&Date.parse(b.starts_at)>Date.now());}
  function bookingRows(merchant=false){const rows=[...(merchant?agendaRows().filter(b=>(state.bookingAgendaStatus==='all'||b.status===state.bookingAgendaStatus)&&(!state.bookingAgendaSearch||String(b.booking_name||'').toLocaleLowerCase('it').includes(state.bookingAgendaSearch.toLocaleLowerCase('it')))):state.bookings)].sort((a,b)=>Number(['pending','confirmed'].includes(b.status))-Number(['pending','confirmed'].includes(a.status))||Date.parse(a.starts_at)-Date.parse(b.starts_at));return rows.length?rows.map(b=>{const future=Date.parse(b.starts_at)>Date.now(),pending=b.status==='pending',confirmed=b.status==='confirmed',active=pending||confirmed;return `<article class="card stack"><div class="row between"><h3>${merchant?e(new Intl.DateTimeFormat('it-IT',{timeZone:'Europe/Rome',hour:'2-digit',minute:'2-digit'}).format(new Date(b.starts_at)))+' · ':''}${e(merchant?b.booking_name:b.restaurant_name)}</h3><span class="pill">${e(b.arrived_at&&b.status==='confirmed'?'Arrivato':bookingStatuses[b.status]||b.status)}</span></div><p><strong>${e(bookingDate(b.starts_at))}</strong> · ${Number(b.party)} persone${merchant?' · '+e(bookingSources[b.source||'online']||b.source):''}</p>${b.discount_percent!=null?`<div class="booking-discount"><strong>−${Number(b.discount_percent)}% · GoodDiner Rewards</strong><small>${active?(b.discount_valid?'Buono associato alla prenotazione':'Buono da verificare: non applicare automaticamente'):b.status==='completed'&&b.discount_valid?'Buono utilizzato':'Sconto associato alla richiesta originale'}</small></div>`:'<p class="small muted">Senza buono sconto</p>'}<div class="booking-actions">${merchant&&canShowBookingProfile(b)?button((bookingReputationEnabled||state.user?.id==='preview-only-user')?'Profilo cliente':'Profilo cliente · in preparazione','booking-profile','btn-outline','data-id="'+e(b.id)+'"'): ''}${merchant&&active&&future&&!b.arrived_at?button('Modifica','register-edit','btn-outline','data-id="'+e(b.id)+'"'):''}${!merchant&&confirmed&&future?button('Calendario','booking-calendar','btn-outline','data-id="'+e(b.id)+'"'):''}${!merchant&&bookingReputationEnabled&&canShowBookingProfile(b)?button('Autorizza consultazione','booking-profile-allow','btn-outline','data-id="'+e(b.id)+'"')+button('Revoca autorizzazione','booking-profile-revoke','btn-outline','data-id="'+e(b.id)+'"'):''}${merchant&&confirmed&&!b.arrived_at&&romeDay(new Date(b.starts_at))===romeDay()&&Date.parse(b.starts_at)<=Date.now()+7200000?button('Segna arrivato','booking-arrive','btn-outline','data-id="'+e(b.id)+'"'):''}${merchant&&pending&&future?`${b.discount_percent==null||b.discount_valid?button('Accetta','booking-confirm','btn-dark','data-id="'+e(b.id)+'"'):''}${button('Rifiuta','booking-reject','btn-outline','data-id="'+e(b.id)+'"')}`:''}${active&&!b.arrived_at&&(future||pending)?button('Annulla','booking-cancel','btn-outline','data-id="'+e(b.id)+'"'):''}${merchant&&confirmed&&!future?(b.discount_percent!=null&&b.discount_valid?button('Riscatta al conto','booking-redeem','btn-dark','data-id="'+e(b.id)+'"'):b.discount_percent==null?button('Completa visita','booking-complete','btn-dark','data-id="'+e(b.id)+'"'):''):''}${merchant&&confirmed&&!b.arrived_at&&Date.parse(b.starts_at)+1800000<=Date.now()?button('Cliente assente','booking-no_show','btn-outline','data-id="'+e(b.id)+'"'):''}</div></article>`;}).join(''):empty('Nessuna prenotazione','Le richieste e le conferme compariranno qui.');}
  const foldSearch=x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('it-IT').trim();
  function bookingCatalogRows(query){if(state.bookingCatalogUnavailable)return notice('Impossibile caricare i ristoranti prenotabili. Premi Aggiorna per riprovare.','alert');if(!state.bookingCatalog.length)return empty('Nessun locale attualmente prenotabile','La registrazione di un ristorante non abilita automaticamente le prenotazioni online. Puoi cercare le schede pubblicate in Scopri i locali.');const terms=foldSearch(query).split(/\s+/).filter(Boolean),rows=state.bookingCatalog.filter(o=>{const hay=foldSearch([o.name,o.city,o.address].join(' '));return terms.every(term=>hay.includes(term));});return rows.length?rows.map(o=>`<article class="item"><div class="item-main"><strong>${e(o.name)}</strong><small>${e(o.city)}${o.address?' · '+e(o.address):''}${o.percent?' · premio −'+Number(o.percent)+'%':''}</small></div>${button('Prenota','booking-select','btn-dark btn-small','data-id="'+e(o.id)+'"')}</article>`).join(''):empty('Nessun locale prenotabile corrisponde','Prova un altro nome o città, oppure cerca tra le schede pubblicate.');}
  function mountBookingSearch(){const input=document.getElementById('gd-booking-search'),out=document.getElementById('gd-booking-results');if(!input||!out)return;input.addEventListener('input',()=>{state.bookingQuery=input.value.slice(0,100);out.innerHTML=bookingCatalogRows(state.bookingQuery);});}
  function customerBookingView(){
    const venue=state.bookingVenue,tab=state.customerBookingTab||'discover',searched=state.bookingSlots!==null,held=new Set(state.bookings.filter(b=>['pending','confirmed'].includes(b.status)).map(b=>b.voucher_id));
    const eligible=venue&&rewardsEnabled?ownVouchers().filter(v=>!held.has(v.id)&&(v.status==='available'&&v.reward_restaurant_id===venue.id||v.status==='pending'&&venue.percent!=null)):[];
    const tabs=`<nav class="gd-booking-tabs" aria-label="Prenotazioni">${[['discover','Prenota'],['history','Le mie'],['wait','In attesa']].map(([id,label])=>button(label,'customer-booking-tab','btn-'+(tab===id?'dark':'outline'),'data-id="'+id+'"')).join('')}</nav>`;
    const form=venue?`<section class="card stack gd-booking-card gd-venue-booking"><div class="row between gd-venue-title"><div class="item-main"><h2>${e(venue.name)}</h2><p class="small muted">${e([venue.city,venue.address].filter(Boolean).join(' · '))}</p></div>${button('Cambia','booking-back','btn-ghost btn-small')}</div><form id="booking-create-form" class="stack">${bookingTimePicker(venue)}${searched?`${eligible.length?`<label>Buono sconto (facoltativo)<select name="voucher"><option value="">Nessun buono</option>${eligible.map(v=>`<option value="${e(v.id)}" ${state.bookingDraft?.voucher===v.id?'selected':''}>Premio ${Number(v.milestone)} · −${Number(v.status==='available'?v.discount_percent:venue.percent)}%</option>`).join('')}</select></label>`:'<input type="hidden" name="voucher" value="">' }${state.bookingSlots.length?`<button type="submit" class="btn btn-dark btn-block">${bookingInstant(state.bookingDraft?.party)?'Prenota ora':'Richiedi prenotazione'}</button><p class="small muted">${bookingInstant(state.bookingDraft?.party)?'Conferma immediata · Nessun pagamento online':'Da 9 persone, conferma del locale'}</p>`:'<button type="submit" class="btn btn-outline btn-block" name="intent" value="wait">Entra in lista d’attesa</button>'}` :''}</form></section>`:`<section class="card stack gd-booking-card"><h2>Scegli il ristorante</h2><label for="gd-booking-search">Cerca nome, città o indirizzo</label><input id="gd-booking-search" type="search" maxlength="100" value="${e(state.bookingQuery||'')}" placeholder="Nome o città" autocomplete="off"><div id="gd-booking-results" aria-live="polite">${bookingCatalogRows(state.bookingQuery)}</div>${button('Scopri i locali pubblicati','partner-directory-open','btn-outline btn-block')}</section>`;
    return `<div class="page-head gd-booking-head"><div><span class="label">GOODDINER · PRENOTAZIONI</span><h1>${tab==='history'?'Le mie prenotazioni':tab==='wait'?'Lista d’attesa':'Prenota un tavolo'}</h1></div>${button('Aggiorna','booking-open','btn-outline btn-small')}</div>${tabs}${state.bookingPartial?notice('Alcune informazioni non sono disponibili. Le prenotazioni caricate restano consultabili; premi Aggiorna per riprovare.','alert'):''}${tab==='history'?`<div class="list gd-booking-list">${bookingRows()}</div>`:tab==='wait'?onlineWaitView():form}`;
  }
  async function roomRPC(action,payload={}){const uid=state.user?.id,r=verifiedRestaurant();if(!uid||!r||state.side!=='merchant')throw Error('Area ristoratore richiesta.');const {data,error}=await sb.rpc('gooddiner_room',{p_action:action,p_payload:{restaurant_id:r.id,day:state.roomDay||romeDay(),...payload}});if(uid!==state.user?.id)throw Error('Account cambiato.');if(error)throw Error(({ROOM_DISABLED:'La gestione tavoli è disattivata.',ROOM_TABLE_BUSY:'Tavolo occupato o già assegnato in questa fascia.',ROOM_CAPACITY:'I tavoli scelti non hanno abbastanza posti.',ROOM_TABLE_ASSIGNED:'Il tavolo è associato a una prenotazione attiva.',ROOM_ASSIGN_FIRST:'Assegna prima un tavolo.',ROOM_BOOKING_INVALID:'La prenotazione non è modificabile in questo stato.',ROOM_INVALID:'Controlla i dati del tavolo.'})[error.message]||(error.code==='23505'?'Numero tavolo o posizione già utilizzati.':'Operazione sala non riuscita.'));return data;}
  async function openRoom(){if(!state.bookingSettings?.room_enabled){toast('Attiva la gestione tavoli nelle impostazioni.');return;}if(!state.roomDay)state.roomDay=state.bookingAgendaDay||romeDay();state.roomData=await roomRPC('list');state.bookingAgendaPanel='room';state.view='booking-merchant';render();}
  function roomTableState(t){const list=(state.roomData?.bookings||[]).filter(b=>['pending','confirmed'].includes(b.status)&&(b.table_ids||[]).includes(t.id));const seated=list.find(b=>b.arrived_at&&b.status==='confirmed');return {kind:!t.active?'inactive':seated?'occupied':list.length?'reserved':'free',list};}
  function roomView(){const data=state.roomData;if(!data)return notice('Carica la sala per iniziare.');const tables=data.tables||[],bookings=data.bookings||[],zones=[...new Set(tables.filter(t=>t.active).map(t=>t.zone))],zone=zones.includes(state.roomZone)?state.roomZone:zones[0]||'',visible=tables.filter(t=>t.active&&t.zone===zone),roomFilter=state.roomFilter||'all',shown=visible.filter(t=>roomFilter==='all'||roomTableState(t).kind===roomFilter),sel=tables.find(t=>t.id===state.roomEdit),b=bookings.find(x=>x.id===state.roomBooking),active=bookings.filter(x=>['pending','confirmed'].includes(x.status)),counts={free:0,reserved:0,occupied:0};tables.filter(t=>t.active).forEach(t=>counts[roomTableState(t).kind]++);return `<section class="card stack"><div class="row between"><div><span class="label">SALA DIGITALE</span><h2>Pianta dei tavoli</h2></div>${button('Aggiorna','room-open','btn-outline btn-small')}</div><form id="room-day-form" class="row"><label>Giorno<input name="day" type="date" required value="${e(state.roomDay)}"></label><button type="submit" class="btn btn-outline">Mostra</button></form><div class="stats"><div class="stat"><small>Liberi</small><strong>${counts.free}</strong></div><div class="stat"><small>Prenotati</small><strong>${counts.reserved}</strong></div><div class="stat"><small>Occupati</small><strong>${counts.occupied}</strong></div></div><p class="small muted">Prenotato = almeno una prenotazione attiva nel giorno scelto. Occupato = arrivo registrato e visita non conclusa.</p><div class="booking-actions">${zones.map(z=>button(e(z),'room-zone','btn-'+(z===zone?'dark':'outline')+' btn-small','data-id="'+e(z)+'"')).join('')}</div><div class="booking-actions">${button('Pianta','room-view-mode','btn-'+(!state.roomListMode?'dark':'outline'),'data-id="map"')}${button('Elenco','room-view-mode','btn-'+(state.roomListMode?'dark':'outline'),'data-id="list"')}</div>${state.roomListMode?`<div class="booking-actions">${[['all','Tutti'],['free','Liberi'],['reserved','Prenotati'],['occupied','Occupati']].map(([id,label])=>button(label,'room-filter','btn-'+(roomFilter===id?'dark':'outline'),'data-id="'+id+'"')).join('')}</div><div class="gd-room-list">${shown.length?shown.map(t=>{const a=roomTableState(t);return `<button type="button" class="room-table room-${a.kind}" data-action="room-table" data-id="${e(t.id)}"><strong>${e(t.label)}</strong><small>${Number(t.seats)} posti · ${a.kind==='free'?'Libero':a.kind==='reserved'?'Prenotato':'Occupato'}</small></button>`;}).join(''):empty('Nessun tavolo','Cambia filtro o zona.')}</div>`:visible.length?`<div class="room-scroll"><div id="room-layout-grid" class="room-grid ${state.roomMoveMode?'room-moving':''}" style="grid-template-columns:repeat(${Math.max(3,...visible.map(t=>t.pos_x))},minmax(80px,1fr));grid-template-rows:repeat(${Math.max(2,...visible.map(t=>t.pos_y))},minmax(76px,auto))">${visible.map(t=>{const a=roomTableState(t);return `<button type="button" data-action="room-table" data-id="${e(t.id)}" class="room-table room-${a.kind}" style="grid-column:${Number(t.pos_x)};grid-row:${Number(t.pos_y)}"><strong>${e(t.label)}</strong><small>${Number(t.seats)} posti</small><small>${a.kind==='occupied'?'Occupato':a.kind==='reserved'?'Prenotato':'Libero'}</small></button>`;}).join('')}</div></div>`:empty('Nessun tavolo','Aggiungi il primo tavolo del locale.')}${!state.roomListMode?button(state.roomMoveMode?'Termina disposizione':'Sposta tavoli','room-move-toggle','btn-outline btn-block'):''}${state.roomMoveMode?'<p class="small muted">Trascina un tavolo su una cella libera della griglia. Per spostamenti più ampi usa colonna e riga nella modifica del tavolo.</p>':''}${button('Aggiungi tavolo','room-new','btn-dark btn-block')}</section>${state.roomEdit!==null?`<section class="card stack"><h2>${sel?'Modifica '+e(sel.label):'Nuovo tavolo'}</h2>${sel?roomTableState(sel).list.map(x=>`<p class="small muted">${e(bookingDate(x.starts_at))} · ${e(x.booking_name)} · ${Number(x.party)} persone${x.discount_percent?' · −'+Number(x.discount_percent)+'%':''}</p>`).join(''):''}<form id="room-table-form" class="stack"><label>Numero o nome<input name="label" maxlength="30" required value="${e(sel?.label||'')}" placeholder="T1"></label><label>Zona<input name="zone" maxlength="60" required value="${e(sel?.zone||zone||'Sala interna')}"></label><label>Posti<input name="seats" type="number" min="1" max="30" required value="${sel?.seats||4}"></label><div class="reward-map-filters"><label>Colonna<input name="x" type="number" min="1" max="12" required value="${sel?.pos_x||1}"></label><label>Riga<input name="y" type="number" min="1" max="20" required value="${sel?.pos_y||1}"></label></div><button class="btn btn-dark" type="submit">Salva tavolo</button></form>${sel?button(sel.active?'Disattiva tavolo':'Riattiva tavolo','room-toggle','btn-outline','data-id="'+e(sel.id)+'"'):''}${button('Chiudi','room-edit-close','btn-ghost')}</section>`:''}${tables.some(t=>!t.active)?`<details class="card"><summary>Tavoli disattivati</summary>${tables.filter(t=>!t.active).map(t=>button(e(t.label)+' · '+e(t.zone),'room-table','btn-outline','data-id="'+e(t.id)+'"')).join('')}</details>`:''}<section class="card stack"><h2>Assegnazione prenotazioni</h2><p class="small muted">Seleziona la prenotazione, poi uno o più tavoli. L'assegnazione automatica sceglie il tavolo singolo libero più adatto.</p>${active.length?`<form id="room-booking-select-form" class="stack"><label>Prenotazione<select name="booking" required><option value="">Scegli</option>${active.map(x=>`<option value="${e(x.id)}" ${x.id===state.roomBooking?'selected':''}>${e(bookingDate(x.starts_at))} · ${e(x.booking_name)} · ${Number(x.party)} persone</option>`).join('')}</select></label><button class="btn btn-outline" type="submit">Seleziona</button></form>`:notice('Nessuna prenotazione attiva per questa data.')}${b?`<article class="card stack"><h3>${e(b.booking_name)} · ${Number(b.party)} persone</h3><p>${e(bookingDate(b.starts_at))} · ${e(bookingStatuses[b.status]||b.status)}</p>${b.discount_percent!=null?`<div class="booking-discount">−${Number(b.discount_percent)}% · Rewards (verifica validità in agenda)</div>`:''}<p class="small muted">Tavoli: ${e(tables.filter(t=>(b.table_ids||[]).includes(t.id)).map(t=>t.label).join(', ')||'Non assegnati')}</p>${b.arrived_at?notice('Arrivo registrato. Completa la visita o riscatta il buono in agenda.'):`<form id="room-assign-form" class="stack">${tables.filter(t=>t.active).map(t=>`<label><input type="checkbox" name="tables" value="${e(t.id)}" ${(b.table_ids||[]).includes(t.id)?'checked':''}> ${e(t.label)} · ${e(t.zone)} · ${Number(t.seats)} posti</label>`).join('')}<button class="btn btn-dark" type="submit">Assegna tavoli selezionati</button></form><div class="booking-actions">${button('Assegna in automatico','room-auto','btn-outline')}${b.table_ids?.length?button('Rimuovi assegnazione','room-unassign','btn-outline'):''}</div>${b.status==='confirmed'&&b.table_ids?.length?button('Segna cliente arrivato','room-arrive','btn-dark btn-block'):''}`}</article>`:''}</section>`;}
  async function registerRPC(action,payload={}){const uid=state.user?.id,r=verifiedRestaurant();if(!uid||!r||state.side!=='merchant')throw Error('Area ristoratore richiesta.');const {data,error}=await sb.rpc('gooddiner_manager_register',{p_action:action,p_payload:{restaurant_id:r.id,...payload}});if(uid!==state.user?.id)throw Error('Account cambiato.');if(error)throw Error(({BOOKING_SLOT_FULL:'Non ci sono abbastanza coperti disponibili in questa fascia.',BOOKING_INVALID:'Controlla nome, data, orario e persone.',BOOKING_INVALID_STATUS:'La prenotazione non è più modificabile.',ROOM_ASSIGN_FIRST:'Configura almeno un tavolo attivo prima di attivare l’assegnazione automatica.'})[error.message]||'Operazione non riuscita. Aggiorna e riprova.');return data;}
  const bookingSources={online:'GoodDiner',phone:'Telefono',walk_in:'Walk-in',waitlist:'Lista d’attesa'};
  const bookingClock=x=>new Intl.DateTimeFormat('it-IT',{timeZone:'Europe/Rome',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(x));
  async function insightRPC(action,payload={}){const uid=state.user?.id;if(!uid)throw Error('Accedi prima di continuare.');const {data,error}=await sb.rpc('gooddiner_manager_insights',{p_action:action,p_payload:payload});if(uid!==state.user?.id)throw Error('Account cambiato.');if(error)throw Error(({WAIT_INVALID:'Richiesta non disponibile o scaduta.',WAIT_LIMIT:'Hai raggiunto il limite di richieste in attesa.',BOOKING_SLOT_FULL:'La fascia non è più disponibile.',BOOKING_VOUCHER_UNAVAILABLE:'Il buono non è più disponibile.'})[error.message]||(error.code==='23505'?'Sei già in lista per questo locale e giorno.':'Operazione non riuscita. Aggiorna e riprova.'));return data;}
  function onlineWaitView(merchant=false){const items=state.onlineWait||[];return `<section class="card stack"><h2>${merchant?'Richieste online in attesa':'Le mie richieste in lista d’attesa'}</h2><p class="small muted">${merchant?'Proponi un orario disponibile. Il posto non viene riservato finché il cliente non accetta.':'Controlla qui le proposte dei locali. Il posto non è garantito fino alla prenotazione e all’eventuale conferma.'}</p>${button('Aggiorna attese','online-wait-refresh','btn-outline btn-small')}${items.length?items.map(w=>{const offered=w.status==='offered'&&Date.parse(w.offer_expires_at)>Date.now(),active=['waiting','offered'].includes(w.status),venue=state.bookingCatalog.find(x=>x.id===w.restaurant_id),held=new Set(state.bookings.filter(x=>['pending','confirmed'].includes(x.status)).map(x=>x.voucher_id)),vouchers=!merchant&&venue&&rewardsEnabled?ownVouchers().filter(v=>!held.has(v.id)&&(v.status==='available'&&v.reward_restaurant_id===venue.id||v.status==='pending'&&venue.percent!=null)):[];return `<article class="card stack"><h3>${e(merchant?w.booking_name:w.restaurant_name)} · ${Number(w.party)} persone</h3><p>${e(w.desired_day)} · ${e(({waiting:'In attesa',offered:offered?'Proposta disponibile':'Proposta scaduta',booked:'Prenotazione creata',cancelled:'Annullata',expired:'Scaduta'})[w.status]||w.status)}</p>${offered?`<p><strong>Orario proposto: ${e(bookingDate(w.offered_at))}</strong></p><p class="small muted">Accettazione entro ${e(bookingDate(w.offer_expires_at))}.</p>`:''}${merchant&&active?`<form id="online-offer-${e(w.id)}" data-id="${e(w.id)}" class="stack"><div class="reward-map-filters"><label>Data<input type="date" name="day" required value="${e(w.desired_day)}"></label><label>Ora<input type="time" name="time" step="1800" required></label></div><button type="submit" class="btn btn-dark">Proponi orario</button></form>`:!merchant&&offered?`<form id="online-accept-${e(w.id)}" data-id="${e(w.id)}" class="stack">${vouchers.length?`<label>Buono sconto<select name="voucher"><option value="">Nessun buono</option>${vouchers.map(v=>`<option value="${e(v.id)}">Premio ${Number(v.milestone)} · −${Number(v.status==='available'?v.discount_percent:venue.percent)}%</option>`).join('')}</select></label>`:''}<button type="submit" class="btn btn-dark">Accetta proposta</button></form>`:''}${active?button('Annulla attesa','online-wait-cancel','btn-outline','data-id="'+e(w.id)+'"'):''}</article>`;}).join(''):empty('Nessuna richiesta','Le richieste online appariranno qui.')}</section>`;}
  function managerReportView(){const r=state.managerReport,from=state.reportFrom||romeDay(new Date(Date.now()-30*86400000)),to=state.reportTo||romeDay();const metrics=[['Prenotazioni','total'],['In attesa','pending'],['Confermate','confirmed'],['Completate','completed'],['Coperti serviti','covers'],['No-show','no_show'],['Annullate','cancelled'],['Rifiutate','rejected'],['Con buono','discounted'],['Buoni riscattati','redeemed']];return `<section class="card stack"><h2>Statistiche del locale</h2><form id="manager-report-form" class="stack"><div class="reward-map-filters"><label>Dal<input type="date" name="from" required value="${e(from)}"></label><label>Al<input type="date" name="to" required value="${e(to)}"></label></div><button type="submit" class="btn btn-dark">Calcola statistiche</button></form>${r?`<div class="stats report-stats">${metrics.map(([label,k])=>`<div class="stat"><small>${label}</small><strong>${Number(r[k])}</strong></div>`).join('')}</div><h3>Provenienza prenotazioni</h3>${[['GoodDiner','online'],['Telefono','phone'],['Walk-in','walk_in'],['Attesa manuale','waitlist']].map(([label,k])=>`<div class="stack"><div class="row between"><span>${label}</span><strong>${Number(r[k])}</strong></div><progress max="${Math.max(1,Number(r.total))}" value="${Number(r[k])}"></progress></div>`).join('')}<p class="small muted">Coperti serviti: prenotazioni completate. I conteggi si riferiscono al periodo selezionato e non sono stime.</p>`:notice('Seleziona un periodo per consultare i dati reali.')}</section>`;}
  function registerPanel(){if(!state.registerData)return '';const b=state.bookings.find(x=>x.id===state.registerEdit);const current=new Date(Math.floor(Date.now()/1800000)*1800000);return `<section class="card stack"><div class="row between"><h2>Registro unico</h2>${button(state.registerForm?'Chiudi':'Nuova prenotazione','register-new','btn-dark btn-small')}</div><p class="small muted">Inserisci le prenotazioni telefoniche e i clienti arrivati senza prenotazione, senza creare profili GoodDiner.</p>${state.registerForm||b?`<form id="register-booking-form" class="stack"><h3>${b?'Modifica prenotazione':'Nuova prenotazione / attesa'}</h3>${!b?`<label>Provenienza<select name="source"><option value="phone">Telefono</option><option value="walk_in">Walk-in</option><option value="waitlist">Lista d’attesa</option></select></label>`:''}<label>Nominativo<input name="name" minlength="2" maxlength="80" required value="${e(b?.booking_name||'')}" placeholder="Nome per la prenotazione"></label><div class="reward-map-filters"><label>Data<input name="day" type="date" required value="${e(b?romeDay(new Date(b.starts_at)):state.bookingAgendaDay||romeDay())}"></label><label>Ora<input name="time" type="time" step="1800" required value="${e(b?bookingClock(b.starts_at):bookingClock(current))}"></label></div><label>Persone<input name="party" type="number" min="1" max="30" required value="${b?Number(b.party):2}"></label>${b?'<p class="small muted">Il buono resta associato. Il tavolo precedente viene liberato: assegnane uno compatibile con il nuovo orario. Concorda la modifica con il cliente.</p>':'<p class="small muted">Per un walk-in indica la mezz’ora corrente; dopo il salvataggio assegna il tavolo e registra l’arrivo. La lista d’attesa non occupa coperti.</p>'}<button class="btn btn-dark" type="submit">${b?'Salva modifica':'Salva nel registro'}</button>${button('Annulla','register-close','btn-outline')}</form>`:''}</section>`;}
  function registerWaitlist(){if(!state.registerData)return notice('Carica il registro.');const list=state.registerData.waitlist||[];return `<section class="card stack"><h2>Lista d’attesa</h2><p class="small muted">Contatta il cliente o concorda direttamente il nuovo orario prima di trasformare l’attesa in una prenotazione. I posti vengono verificati al momento della conversione.</p>${button('Aggiungi richiesta','register-wait-new','btn-dark')}${state.registerForm?registerPanel():''}${list.length?list.map(w=>`<article class="card stack"><h3>${e(w.booking_name)} · ${Number(w.party)} persone</h3><p>Orario richiesto: ${e(bookingDate(w.desired_at))}</p><form id="register-wait-${e(w.id)}" data-id="${e(w.id)}" class="stack"><div class="reward-map-filters"><label>Data concordata<input type="date" name="day" required value="${e(romeDay(new Date(w.desired_at)))}"></label><label>Orario<input type="time" step="1800" name="time" required value="${e(bookingClock(w.desired_at))}"></label></div><button class="btn btn-dark" type="submit">Conferma e trasferisci in agenda</button></form>${button('Rimuovi dalla lista','register-wait-cancel','btn-outline','data-id="'+e(w.id)+'"')}</article>`).join(''):empty('Nessuno in attesa','Le richieste in lista appariranno qui.')}</section>`;}
  function registerAuto(){return state.bookingSettings?.room_enabled&&state.registerData?`<section class="card stack"><h2>Assegnazione automatica tavoli</h2><form id="register-auto-form" class="stack"><label><input type="checkbox" name="enabled" ${state.registerData.auto_confirm?'checked':''}> Assegna automaticamente un tavolo singolo compatibile</label><p class="small muted">L’assegnazione è facoltativa e non cambia la conferma della prenotazione. Se non c’è un tavolo singolo compatibile, assegna i tavoli manualmente.</p><button class="btn btn-dark" type="submit">Salva preferenza</button></form></section>`:'';}
  function bookingControl(){const s=state.bookingSettings;if(!s||!state.merchantLicense?.is_usable)return '';const ready=s.enabled&&Number(state.bookingSchedule?.capacity)>0&&state.bookingSchedule?.windows?.length;return `<section class="gd-reception"><div><span class="gd-kicker">PRENOTAZIONI ONLINE</span><strong>${!ready?'Da configurare':s.online_paused?'Sospese':'Attive'}</strong><small>${s.online_paused?'Le prenotazioni esistenti restano valide.':!ready?'Completa orari, coperti e ricezione.':'Ricevi nuove prenotazioni.'}</small></div>${ready?button(s.online_paused?'Riattiva':'Sospendi','booking-pause-toggle','btn-outline gd-control-btn'):button('Configura','booking-settings-panel','btn-outline gd-control-btn')}</section>`;}
  async function changeBookingControl(kind){if(state.side!=='merchant'||!verifiedRestaurant()||!state.bookingSettings)return;const uid=state.user.id,generation=accountLoadGeneration,venue=verifiedRestaurant().id,key=kind==='pause'?'online_paused':'room_enabled',enabled=!state.bookingSettings[key];if(kind==='pause'&&enabled&&!window.confirm('Sospendere le nuove prenotazioni online? Quelle esistenti restano valide.'))return;busy(true);try{const settings=await bookingRPC(kind==='pause'?'pause_set':'room_set',{restaurant_id:venue,enabled});if(uid!==state.user?.id||generation!==accountLoadGeneration)return;state.bookingSettings=settings;if(kind==='room'&&!enabled){state.roomData=null;state.roomEdit=null;state.roomBooking=null;if(state.bookingAgendaPanel==='room')state.bookingAgendaPanel='service';if(state.registerData)state.registerData.auto_confirm=false;}render();toast(kind==='pause'?(enabled?'Prenotazioni sospese.':'Prenotazioni riattivate.'):(enabled?'Gestione tavoli attivata.':'Gestione tavoli disattivata.'));}finally{if(uid===state.user?.id&&generation===accountLoadGeneration)busy(false);}}
  function roomPreference(){return state.bookingSettings?`<section class="card stack gd-booking-card"><div class="row between"><div><h2>Gestione tavoli</h2><p class="small muted">Facoltativa. Puoi gestire il servizio solo con i coperti.</p></div>${button(state.bookingSettings.room_enabled?'Disattiva':'Attiva','booking-room-toggle','btn-outline btn-small')}</div><span class="gd-state">${state.bookingSettings.room_enabled?'Attiva':'Disattivata'}</span></section>`:'';}
  function bookingVisibilityNotice(){const venue=verifiedRestaurant();if(!venue)return notice('Il locale deve essere verificato.');if(!state.merchantLicense?.is_usable)return notice('Prenotazioni online non disponibili: accesso Business non attivo.','alert');if(!state.bookingSettings)return notice('Stato prenotazioni non disponibile: premi Aggiorna per verificarlo.','alert');if(state.bookingSettings.online_paused)return notice('Le nuove prenotazioni online sono sospese. Le prenotazioni già ricevute restano valide.');if(!state.bookingSettings.enabled)return notice('Prenotazioni online disattivate: il locale non compare tra quelli prenotabili. Apri Disponibilità e abilita le richieste.','alert');if(!state.bookingSchedule)return notice('Impossibile verificare orari e coperti. Premi Aggiorna.','alert');if(!(Number(state.bookingSchedule.capacity)>0)||!state.bookingSchedule.windows?.length)return notice('Configurazione incompleta: salva almeno una fascia oraria e il numero di coperti online per comparire nella ricerca.','alert');return notice('Prenotazioni online configurate. Il locale può comparire nella ricerca degli altri clienti.');}
  function merchantBookingView(){const settings=state.bookingSettings,rows=agendaRows(),active=rows.filter(b=>['pending','confirmed'].includes(b.status)),confirmed=rows.filter(b=>b.status==='confirmed'),future=confirmed.filter(b=>Date.parse(b.starts_at)>Date.now());const panel=state.bookingAgendaPanel||'service',settingsTab=state.merchantSettingsTab||'hours';return `<div class="page-head gd-booking-head"><div><span class="label">GOODDINER · MANAGER</span><h1>Gestione prenotazioni</h1></div>${button('Aggiorna','booking-merchant','btn-outline btn-small')}</div>${state.bookingPartial?notice('Alcuni strumenti non sono disponibili. L’agenda caricata resta consultabile; premi Aggiorna per riprovare.','alert'):''}${bookingControl()}${state.bookingAgendaPanel==='settings'?bookingVisibilityNotice():''}<nav class="gd-booking-tabs gd-manager-tabs ${settings?.room_enabled?'':'gd-no-room'}" aria-label="Gestione prenotazioni">${button('Agenda','booking-agenda-panel','btn-'+(state.bookingAgendaPanel==='service'?'dark':'outline'))}${settings?.room_enabled?button('Sala','room-open','btn-'+(state.bookingAgendaPanel==='room'?'dark':'outline')):''}${button('Attesa','register-wait-panel','btn-'+(state.bookingAgendaPanel==='waitlist'?'dark':'outline'))}${button('Disponibilità','booking-settings-panel','btn-'+(state.bookingAgendaPanel==='settings'?'dark':'outline'))}</nav>${state.bookingAgendaPanel==='room'?roomView():state.bookingAgendaPanel==='waitlist'?registerWaitlist()+onlineWaitView(true):state.bookingAgendaPanel==='settings'?`<nav class="gd-booking-tabs" aria-label="Impostazioni prenotazioni">${[['hours','Orari e coperti'],['options','Ricezione'],['report','Statistiche']].map(([id,label])=>button(label,'merchant-settings-tab','btn-'+(settingsTab===id?'dark':'outline'),'data-id="'+id+'"')).join('')}</nav>${settingsTab==='hours'?scheduleForm()||notice('Disponibilità non caricata. Premi Aggiorna.','alert'):settingsTab==='report'?managerReportView():`${settings?`<section class="card stack"><h2>Ricezione prenotazioni</h2><form id="booking-settings-form" class="stack"><label><input type="checkbox" name="enabled" ${settings.enabled?'checked':''}> Accetta prenotazioni online</label><label>Massimo persone per prenotazione<input type="number" min="1" max="30" name="max_party" required value="${Number(settings.max_party)}"></label><button class="btn btn-dark" type="submit">Salva impostazioni</button></form><p class="small muted">Da 1 a 8 persone: conferma immediata entro la disponibilità. Da 9 persone in su: conferma manuale. Il limite massimo riguarda tutti i gruppi.</p></section>`:''}${roomPreference()}${registerAuto()}`}`:`${registerPanel()}<section class="card stack gd-booking-card"><div class="row between"><h2>Agenda del servizio</h2><span class="pill">${e(state.bookingAgendaDay||'Tutte le date')}</span></div><div class="booking-actions">${button('Oggi','booking-agenda-today','btn-outline btn-small')}${button('Domani','booking-agenda-tomorrow','btn-outline btn-small')}${button('Tutte le date','booking-agenda-all','btn-ghost btn-small')}</div><details class="gd-booking-filters"><summary>Cerca e filtra</summary><form id="booking-agenda-filter" class="stack"><div class="reward-map-filters"><label>Data<input type="date" name="day" value="${e(state.bookingAgendaDay)}"></label><label>Stato<select name="status"><option value="all">Tutti</option>${Object.entries(bookingStatuses).map(([k,v])=>`<option value="${k}" ${state.bookingAgendaStatus===k?'selected':''}>${e(v)}</option>`).join('')}</select></label></div><label>Cerca nominativo<input type="search" name="query" maxlength="80" value="${e(state.bookingAgendaSearch)}" placeholder="Nome della prenotazione"></label><button type="submit" class="btn btn-outline">Applica filtri</button></form></details></section><div class="stats"><div class="stat"><small>Richieste attive</small><strong>${active.length}</strong></div><div class="stat"><small>Coperti confermati</small><strong>${confirmed.reduce((n,b)=>n+Number(b.party),0)}</strong></div><div class="stat"><small>In arrivo</small><strong>${future.length}</strong></div></div><p class="small muted">Riepilogo delle prenotazioni caricate (fino a 300), per la data selezionata.</p><h2 class="section-label">Prenotazioni del giorno</h2><div class="list gd-booking-list">${bookingRows(true)}</div>`}`;}
  async function openBookings(merchant=false,venueId=null){
    if(!state.user)return;
    const uid=state.user.id,generation=accountLoadGeneration,side=state.side,venue=verifiedRestaurant();
    if(merchant&&(!venue||side!=='merchant')||!merchant&&side!=='customer')return;
    const current=()=>uid===state.user?.id&&generation===accountLoadGeneration&&side===state.side&&(!merchant||verifiedRestaurant()?.id===venue.id);
    const licensed=merchant&&state.merchantLicense?.is_usable,previousView=state.view;
    busy(true);
    try{
      const rows=await bookingRPC('list',{mode:merchant?'merchant':'customer',...(merchant?{restaurant_id:venue.id}:{})});
      if(!current())return;
      const optional=async task=>{try{return {ok:true,data:await task()};}catch{return {ok:false,data:null};}};
      const results=merchant?await Promise.all([
        licensed?optional(()=>bookingRPC('settings_get',{restaurant_id:venue.id})):Promise.resolve({ok:true,data:null}),
        licensed?optional(()=>scheduleRPC('schedule_get',{restaurant_id:venue.id})):Promise.resolve({ok:true,data:null}),
        licensed?optional(()=>registerRPC('list')):Promise.resolve({ok:true,data:null}),
        licensed?optional(()=>insightRPC('merchant_list',{restaurant_id:venue.id})):Promise.resolve({ok:true,data:[]}),
        licensed&&state.bookingAgendaPanel==='room'?optional(()=>roomRPC('list')):Promise.resolve({ok:true,data:null})
      ]):await Promise.all([optional(()=>bookingRPC('catalog')),optional(()=>insightRPC('customer_list'))]);
      if(!current())return;
      state.bookings=Array.isArray(rows)?rows:[];state.bookingPartial=results.some(r=>!r.ok);
      if(merchant){
        if(state.view!=='booking-merchant')state.bookingAgendaDay=romeDay();
        state.bookingSettings=results[0].data;if(state.bookingAgendaPanel==='room'&&!state.bookingSettings?.room_enabled)state.bookingAgendaPanel='service';state.bookingSchedule=results[1].data;state.registerData=results[2].data;state.onlineWait=results[3].data||[];
        state.roomData=results[4].data;
        if(!licensed||state.bookingAgendaPanel==='room'&&!results[4].ok)state.bookingAgendaPanel='service';
        state.section='merchant';state.view='booking-merchant';
      }else{
        state.bookingCatalogUnavailable=!results[0].ok||!Array.isArray(results[0].data);state.bookingCatalog=Array.isArray(results[0].data)?results[0].data:[];state.onlineWait=results[1].data||[];
        state.bookingVenue=venueId?state.bookingCatalog.find(x=>x.id===venueId)||null:null;if(venueId||state.view!=='booking-customer')state.customerBookingTab='discover';state.bookingDraft=null;state.bookingSlots=null;state.section='visits';state.view='booking-customer';
      }
      render();if(previousView!==state.view||venueId)window.scrollTo({top:0,behavior:'instant'});
    }finally{if(current())busy(false);}
  }
  function bookingRomeISO(day,time){if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||!/^\d{2}:\d{2}$/.test(time))throw Error('Data e orario non validi.');const target=day+'T'+time;const guess=Date.parse(target+':00Z');if(!Number.isFinite(guess))throw Error('Data non valida.');const fmt=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});for(const offset of [1,2]){const d=new Date(guess-offset*3600000);if(fmt.format(d).replace(' ','T')===target)return d.toISOString();}throw Error('Orario non valido in Italia.');}
  function rewardWallet(){const n=stats().positive%10,items=ownVouchers(),status={pending:'Da attivare',available:'Disponibile',redeemed:'Utilizzato',suspended:'Sospeso'};return `<section class="card stack reward-wallet"><span class="label">GOODDINER REWARDS</span><h2>Il tuo prossimo buono</h2><div class="row between"><strong>${n} / 10 recensioni positive</strong><span class="pill">${10-n} mancanti</span></div><div class="reward-stamps" role="img" aria-label="${n} recensioni positive su 10">${Array.from({length:10},(_,i)=>`<span class="${i<n?'earned':''}">${i<n?'✓':i+1}</span>`).join('')}</div><p class="small muted">Contano solo i voti da 8 a 10 su visite confermate. ${rewardsEnabled?'Ogni 10 positivi maturi un nuovo premio.':'I buoni non sono ancora attivi; il conteggio è solo informativo.'}</p>${button('Mappa locali e sconti','reward-map','btn-outline btn-block')}${!rewardsEnabled?notice('I buoni sconto non sono ancora riscattabili. Le condizioni saranno confermate prima dell’attivazione.'):button('Carica locali per i miei buoni','reward-catalog','btn-outline btn-block')}${items.length?items.map(v=>`<article class="card stack"><div class="row between"><strong>Traguardo: ${Number(v.milestone)} recensioni positive</strong><span class="pill">${e(status[v.status]||v.status)}</span></div>${v.reward_restaurant_id?`<p>${e(state.restaurants.find(r=>r.id===v.reward_restaurant_id)?.name||'Locale selezionato')} · ${Number(v.discount_percent)}% di sconto</p>`:''}${v.status==='available'&&rewardsEnabled?`<code class="reward-code">${e(v.voucher_code)}</code><p class="small muted">Mostralo al ristoratore al momento del conto, dopo il check-in. Un buono per visita.</p><button type="button" class="btn btn-outline" data-action="reward-cancel" data-id="${e(v.id)}">Cambia locale</button>`:''}${v.status==='pending'&&rewardsEnabled?`<form id="reward-claim-${e(v.id)}" data-voucher-id="${e(v.id)}" class="stack"><label>Seleziona un locale aderente<select name="offer" required><option value="">Scegli il ristorante</option>${state.rewardOffers.map(o=>`<option value="${e(o.id)}">${e(o.name)} · ${e(o.city)} · ${Number(o.percent)}%</option>`).join('')}</select></label><button type="submit" class="btn btn-dark" ${state.rewardOffers.length?'':'disabled'}>Attiva il buono</button></form>`:''}</article>`).join(''):''}</section>`;}
  function merchantRewards(){const offer=state.rewardOffer;return `<section class="card stack"><span class="label">GOODDINER REWARDS</span><h2>Buoni sconto del locale</h2><p class="small muted">L'adesione è facoltativa. Lo sconto è a carico del locale, non è cumulabile e si applica una sola volta per visita. ${rewardsEnabled?'I buoni già attivati conservano la percentuale concordata.':'Il programma non è ancora attivo.'}</p>${offer?`<form id="reward-offer-form" class="stack"><label>Percentuale di sconto<input name="percent" type="number" min="1" max="100" step="1" required value="${offer.percent===null?'':Number(offer.percent)}"></label><label><input type="checkbox" name="enabled" ${offer.enabled?'checked':''}> Aderisco e accetto di applicare lo sconto scelto</label><button class="btn btn-dark" type="submit">Salva adesione</button></form>`:button('Configura partecipazione','reward-offer-load','btn-outline')}${rewardsEnabled?`<form id="reward-redeem-form" class="stack"><h3>Riscatta un buono</h3><label>Visita confermata di oggi<select name="visit" required><option value="">Scegli il cliente</option>${state.visits.filter(v=>v.restaurant_id===verifiedRestaurant()?.id&&v.status==='confirmed'&&v.visited_on===new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Rome'})).map(v=>`<option value="${e(v.id)}">${e(v.guest_nickname)} · ${e(v.guest_code)}</option>`).join('')}</select></label><label>Codice buono<input name="code" required autocomplete="off" autocapitalize="characters" pattern="GD-[0-9A-Fa-f]{32}" placeholder="GD-…"></label><button class="btn btn-dark" type="submit">Conferma riscatto</button></form>`:''}</section>`;}
  async function rewardRPC(action,payload={}){const uid=state.user?.id;if(!uid)throw Error('Accedi prima di continuare.');const {data,error}=await sb.rpc('gooddiner_rewards',{p_action:action,p_payload:payload});if(uid!==state.user?.id)throw Error('Account cambiato.');if(error)throw Error(({PREMI_NON_ATTIVI:'Il programma premi non è ancora attivo.',PREMIO_NON_DISPONIBILE:'Premio non disponibile.',OFFERTA_NON_DISPONIBILE:'Il locale non aderisce più.',OFFERTA_MODIFICATA:'Lo sconto è cambiato. Aggiorna le offerte.',BUONO_NON_VALIDO:'Buono non valido, già utilizzato o non associato al cliente.',VISITA_NON_VALIDA:'Serve una visita confermata di oggi.',BUONO_GIA_USATO_PER_VISITA:'È già stato utilizzato un buono per questa visita.'})[error.message]||'Operazione premi non riuscita. Riprova.');return data;}
  function customerReviews(){const s=stats(),reviews=ownReviews(),vouchers=ownVouchers(),disputes=ownDisputes();return `${activityTabs()}<div class="page-head"><div><span class="label">ESPERIENZE</span><h1>Le valutazioni ricevute.</h1><p>Le recensioni sono collegate alle visite confermate.</p></div></div>${!personalReviewsEnabled?notice('Le valutazioni sulle persone sono temporaneamente disattivate. Non vengono creati nuovi voti durante il pilota.'):''}<div class="stats"><div class="stat"><small>Recensioni</small><strong>${s.rated}</strong></div><div class="stat"><small>Positive (8–10)</small><strong>${s.positive}</strong></div><div class="stat"><small>Ristoranti per la collezione</small><strong>${state.dinerpassCollection?Number(state.dinerpassCollection.progress)||0:'—'}</strong></div></div><section class="card stack"><span class="label">DINERPASS COLLEZIONABILI</span><h2>Ogni ristorante conta.</h2><p>Le edizioni speciali si sbloccano con recensioni valide ricevute da ristoranti differenti, indipendentemente dal voto. I buoni sconto seguono invece le valutazioni positive.</p>${button('Apri la mia collezione','collection-open','btn-outline btn-block')}</section><h2 class="section-label">Recensioni</h2>${reviews.length?`<div class="list">${reviews.map(r=>{const dispute=disputes.find(d=>d.review_id===r.id);return `<article class="card"><div class="row between"><div><strong>${e(state.restaurants.find(v=>v.id===r.restaurant_id)?.name||'Ristorante')}</strong><p class="small muted">${e(date(r.created_at))}</p></div><span class="pill">${Number(r.rating)}/10</span></div><p class="muted">${e(r.comment)}</p><p class="small muted">${r.status==='published'?'Visibile a te e al locale autore; condivisione tramite prenotazione non ancora attiva':'Rimossa'}</p>${dispute?`<p class="pill ${dispute.status==='pending'?'pill-warm':'pill-gray'}">${dispute.status==='pending'?'Contestazione in valutazione':dispute.status==='accepted'?'Contestazione accolta':'Contestazione non accolta'}</p><p class="small muted">Richiesta inviata il ${e(date(dispute.created_at))}</p>`:r.status==='published'?`<button class="btn btn-outline btn-small" data-action="dispute" data-id="${e(r.id)}">Contesta la recensione</button>`:''} </article>`;}).join('')}</div>`+historyMoreButton('customerReviews'):empty('Nessuna recensione','Le valutazioni dei ristoratori verificati compariranno qui.')}${rewardWallet()}`;}
  function customerProfile(){const panel=state.profilePanel||'account',p=state.profile,requests=state.privacyRequests.filter(r=>r.requester_id===state.user?.id);const statusLabels={received:'Ricevuta',in_review:'In valutazione',resolved:'Conclusa',rejected:'Respinta'};return `<div class="page-head"><div><span class="label">IMPOSTAZIONI</span><h1>${state.side==='merchant'?'Account del locale':'Il tuo profilo'}</h1><p>Impostazioni, sicurezza e assistenza.</p></div></div><nav class="gd-activity-tabs" aria-label="Impostazioni">${[['account','Account'],['privacy','Privacy'],['tools',state.side==='merchant'?'Locale':'Altro']].map(([id,label])=>button(label,'profile-panel','btn-'+(panel===id?'dark':'outline'),'data-id="'+id+'"')).join('')}</nav>${panel==='account'?`<div class="two-col"><section class="card stack"><h2>Identità GoodDiner</h2>${button('Guida alle funzioni','guide-open','btn-outline btn-block')}<div class="row between"><span class="muted small">Codice personale</span><strong>${e(p.customer_code)}</strong></div><form id="profile-form" class="stack"><div class="field"><label for="gd-profile-nickname">Nickname</label><input id="gd-profile-nickname" name="nickname" required minlength="3" maxlength="30" value="${e(p.nickname)}" autocomplete="nickname"></div><button class="btn btn-dark" type="submit">Salva il nickname</button></form></section><section class="card stack"><h2>Proteggi il tuo account</h2>${isAnon()?`${notice('Questo profilo non è ancora recuperabile. Puoi collegare un’email verificata per mantenerlo anche cambiando dispositivo.','alert')}<form id="link-email-form" class="stack"><div class="field"><label>Email per il recupero</label><input name="email" type="email" required autocomplete="email"></div><button class="btn btn-dark" type="submit">Collega e verifica email</button></form>`:`<p class="muted">Accesso associato a un account permanente.</p><p class="small muted">Email: ${e(state.user.email||'non disponibile')}</p>${state.user.email&&state.user.email_confirmed_at?`<form id="change-password-form" class="stack"><h3>Password per i prossimi accessi</h3><p class="small muted">Imposta o cambia la password del tuo account. Usala per accedere anche da un altro dispositivo.</p><div class="field"><label for="gd-change-password">Nuova password (almeno 10 caratteri)</label><input id="gd-change-password" name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></div><div class="field"><label for="gd-confirm-password">Conferma nuova password</label><input id="gd-confirm-password" name="confirmPassword" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></div><button class="btn btn-dark" type="submit">Salva password</button></form>`:notice('Conferma l’indirizzo email prima di impostare la password.','alert')}`}<button class="btn btn-outline" data-action="signout">${svg('logout')} Esci</button></section></div>`:panel==='tools'?`<section class="card stack"><h2>${state.side==='merchant'?'Gestisci il locale':'Scopri GoodDiner'}</h2>${state.side==='merchant'&&verifiedRestaurant()?button('Indirizzo e premi','venue-tools','btn-outline btn-block')+button('Marketing Kit','marketing-open','btn-outline btn-block')+button('Abbonamento e accesso','merchant-access','btn-outline btn-block'):state.side==='customer'?button('Collezione DinerPass','collection-open','btn-outline btn-block')+button('Scopri i ristoranti','partner-directory-open','btn-outline btn-block')+button('Locali e sconti','reward-map','btn-outline btn-block'):''}${button('Guida alle funzioni','guide-open','btn-outline btn-block')}${button('Assistenza','help','btn-outline btn-block')}${button('Privacy e trasparenza','privacy','btn-outline btn-block')}</section>`:`<section class="card stack privacy-center"><span class="label">PRIVACY · DIRITTI</span><h2>Controlla i tuoi dati.</h2>${state.side==='customer'?`<div class="card stack"><h3>Autorizzazioni privacy</h3><p class="muted">La consultazione delle valutazioni da parte dei ristoratori presso cui prenoti è prevista. Non è ancora attiva: puoi registrare o revocare la tua preferenza e confermarla con l’informativa definitiva.</p>${state.privacyChoices?`<p><strong>${state.privacyChoices.sharing_requested?'Preferenza: interessato alla condivisione':'Preferenza: non condividere'}</strong></p>`:''}${button('Visualizza le mie scelte','privacy-choices','btn-outline btn-block')}${button('Desidero condividere in futuro','privacy-choice-on','btn-outline btn-block')}${button('Non condividere / revoca','privacy-choice-off','btn-outline btn-block')}</div>`:''}${state.side==='customer'&&reputationSharingEnabled?`${button('Chi ha consultato le mie valutazioni','reputation-accesses','btn-outline btn-block')}${button('Revoca le condivisioni precedenti','reputation-revoke','btn-outline btn-block')}<p class="muted small">La revoca impedisce nuove consultazioni delle valutazioni già autorizzate, senza cancellare lo storico privato.</p>${Array.isArray(state.reputationAccesses)?(state.reputationAccesses.length?state.reputationAccesses.map(a=>`<div class="item"><div class="item-main"><strong>${e(a.restaurant)}</strong><small>${e(date(a.accessed_at))}</small></div><span class="pill">${e(String(a.review_count))} valutazioni</span></div>`).join(''):'<p>Nessuna consultazione registrata.</p>'):''}`:''}${state.side==='customer'&&bookingReputationEnabled?`<div class="card stack"><h3>Consultazioni da prenotazioni</h3><p>Verifica quali locali hanno consultato le valutazioni autorizzate.</p>${button('Chi ha consultato le mie valutazioni','booking-profile-accesses','btn-outline btn-block')}${Array.isArray(state.bookingReputationAccesses)?(state.bookingReputationAccesses.length?state.bookingReputationAccesses.map(a=>`<div class="item"><div class="item-main"><strong>${e(a.restaurant)}</strong><small>${e(date(a.accessed_at))}</small></div><span class="pill">${e(String(a.review_count))} valutazioni</span></div>`).join(''):'<p>Nessuna consultazione registrata.</p>'):''}</div>`:''}<p class="muted">Puoi esportare ciò che GoodDiner conserva sul tuo profilo o inviare una richiesta di accesso, correzione, cancellazione, limitazione od opposizione. Le richieste richiedono una valutazione umana.</p>${button('Esporta i miei dati (JSON)','export-data','btn-outline')}<form id="privacy-request-form" class="stack"><div class="field"><label for="gd-privacy-kind">Quale diritto vuoi esercitare?</label><select id="gd-privacy-kind" name="kind" required><option value="access">Accesso ai dati</option><option value="rectification">Rettifica</option><option value="erasure">Cancellazione</option><option value="restriction">Limitazione del trattamento</option><option value="objection">Opposizione</option></select></div><div class="field"><label for="gd-privacy-details">Dettagli utili (facoltativi)</label><textarea id="gd-privacy-details" name="details" maxlength="500" rows="3" placeholder="Spiega brevemente la richiesta, senza inserire dati sensibili."></textarea><small>Massimo 500 caratteri.</small></div><button class="btn btn-dark" type="submit">Invia richiesta</button></form>${requests.length?`<h3>Le tue richieste</h3><div class="list">${requests.map(r=>`<div class="item"><div class="item-main"><strong>${e(({access:'Accesso',rectification:'Rettifica',erasure:'Cancellazione',restriction:'Limitazione',objection:'Opposizione'})[r.request_kind]||r.request_kind)}</strong><small>${e(date(r.created_at))}</small></div><span class="pill ${r.status==='received'||r.status==='in_review'?'pill-warm':'pill-gray'}">${e(statusLabels[r.status]||r.status)}</span></div>`).join('')}</div>`:''}${notice('L’invio non elimina i dati automaticamente. Un incaricato deve valutare la richiesta e comunicare l’esito; la procedura privacy definitiva sarà pubblicata prima dell’apertura.')}</section>`}`;}

  function applicationForm(){const hasInvite=state.merchantInviteStatus===true;return `<section class="card stack"><span class="label">1 / 2 · ATTIVA IL TUO RISTORANTE</span><h2>Crea il profilo del locale</h2><p class="lead">Usa il tuo account attuale. Non serve registrarti di nuovo.</p><form id="application-form" class="stack">${hasInvite?notice('Invito già confermato. Completa i dati del locale.'): `<div class="field"><label for="gd-existing-invite">Codice invito ristoratore ${state.merchantInviteStatus===false?'*':'(se non ancora utilizzato)'}</label><input id="gd-existing-invite" name="inviteCode" autocapitalize="off" autocomplete="off" spellcheck="false" minlength="32" maxlength="32" pattern="[a-fA-F0-9]{32}" placeholder="Incolla il codice ricevuto" ${state.merchantInviteStatus===false?'required':''}><small>Non hai un codice? Contatta il team GoodDiner per riceverne uno.</small></div>`}<div class="field"><label for="gd-venue-name">Nome del ristorante</label><input id="gd-venue-name" name="name" required minlength="3" maxlength="100" placeholder="Es. La Terrazza"></div><div class="field"><label for="gd-venue-city">Città</label><input id="gd-venue-city" name="city" required minlength="2" maxlength="100" placeholder="Es. Torri del Benaco"></div><p class="small muted">Il team GoodDiner verificherà la tua attività prima di attivare le funzioni ristoratore.</p><button type="submit" class="btn btn-dark btn-block">Crea profilo e invia richiesta</button></form></section>`;}
  async function billingPilotCall(action,id,options={}){const venue=verifiedRestaurant(),uid=state.user?.id;if(!billingPilotLink||!venue||!uid||state.side!=='merchant')throw Error('Laboratorio riservato.');const {data,error}=await sb.auth.getSession();if(error||!data?.session?.access_token)throw Error('Accedi nuovamente per continuare.');const response=await fetch('https://'+PROJECT_REF+'.supabase.co/functions/v1/gooddiner-billing-test',{method:'POST',headers:{apikey:cfg.supabasePublishableKey,Authorization:'Bearer '+data.session.access_token,'Content-Type':'application/json'},body:JSON.stringify({action,restaurant_id:venue.id,...(id?{id}:{}),...options}),cache:'no-store'});const result=await response.json();if(state.user?.id!==uid||verifiedRestaurant()?.id!==venue.id||state.side!=='merchant')throw Error('Account cambiato.');if(!response.ok||result.error)throw Error(result.message||'Laboratorio non disponibile per questo account.');return result;}
  function merchantAccessPanel(){
    const r=verifiedRestaurant(),a=state.merchantLicense;if(!r||state.side!=='merchant')return '';
    const labels={trialing:'Periodo di prova',active:'Abbonamento attivo',expired:'Accesso scaduto',suspended:'Accesso sospeso',canceled:'Accesso annullato'};
    const until=a?.active_until?new Date(a.active_until):null,validDate=until&&Number.isFinite(until.getTime()),days=validDate?Math.max(0,Math.ceil((until.getTime()-Date.now())/86400000)):null;
    const status=!a?'Stato non disponibile':a.is_usable?(labels[a.license_status]||'Accesso attivo'):(labels[a.license_status]&& !['active','trialing'].includes(a.license_status)?labels[a.license_status]:'Accesso non attivo');
    return `<section class="card stack"><span class="label">GOODDINER BUSINESS</span><h2>Il tuo abbonamento.</h2><div class="row between"><strong>${e(status)}</strong><span class="pill ${a?.is_usable?'':'pill-warm'}">${a?.is_usable?'Accesso disponibile':'Da verificare'}</span></div>${validDate?`<p>Termine accesso: <strong>${e(date(a.active_until))}</strong></p>${a?.is_usable?`<p>${days} giorni rimanenti.</p>`:''}`:'<p class="muted small">Scadenza non disponibile.</p>'}<p class="small muted">Lo storico rimane consultabile anche dopo la scadenza. Questa schermata non effettua addebiti; il rinnovo commerciale richiede conferma del pagamento.</p>${button('Premi e programma partner','partner-benefits','btn-outline btn-block')}${button('Torna alla panoramica','merchant','btn-outline btn-block')}</section>`;
  }
  function billingPilotPanel(){if(!billingPilotLink)return '';const d=state.billingPilot,runs=d?.runs||[],labels={not_started:'Checkout da completare',active:'Attivo',trialing:'In prova',past_due:'Pagamento in ritardo',unpaid:'Non pagato',paused:'Sospeso',incomplete:'Pagamento incompleto',incomplete_expired:'Scaduto',canceled:'Annullato',checkout_expired:'Checkout scaduto'};return `<section class="card stack"><span class="label">SANDBOX · SOLO AMMINISTRATORE</span><h2>Abbonamento Manager</h2><p><strong>29,90 € / mese oppure 299 € / anno</strong> simulati</p><p class="small muted">Nessun addebito reale. La licenza di prova mostrata qui non abilita o modifica i servizi commerciali.</p>${button('Verifica / aggiorna abbonamento','billing-pilot-status','btn-outline btn-block')}${d?.configured&&!runs.some(r=>r.blocks_checkout)?`<div class="stack" id="billing-pilot-options"><label>Piano<select id="billing-pilot-plan"><option value="monthly">Mensile · 29,90 €</option><option value="annual">Annuale · 299 €</option></select></label><label>Modalità<select id="billing-pilot-trial"><option value="0">Pagamento immediato · codice GDTEST10 facoltativo</option><option value="14">14 giorni gratuiti, poi rinnovo a pagamento</option></select></label><small>Condizioni esclusivamente dimostrative; prova gratuita una sola volta. Le promozioni non si cumulano con la prova.</small>${button('Avvia checkout Sandbox','billing-pilot-checkout','btn-dark btn-block')}</div>`:''}${d&&!d.configured?notice('Configurazione Sandbox incompleta.','alert'):''}${runs.map(r=>`<article class="card stack"><div class="row between"><strong>${e(labels[r.subscription_status]||r.subscription_status)}</strong><span class="pill">${r.test_access?'Licenza simulata attiva':'Licenza simulata non attiva'}</span></div><p class="small">${r.plan_code==='annual'?'Annuale':'Mensile'} · Pagamento: ${r.payment_status==='paid'?'Pagato':'Non pagato'} · Fine periodo: ${r.period_end?e(date(r.period_end)):'—'}</p>${r.trial_end?notice('Fine prova: '+date(r.trial_end)):''}${r.cancel_at_period_end?notice('Disdetta programmata alla fine del periodo.'):''}<div class="booking-actions">${button('Sincronizza','billing-pilot-sync','btn-outline','data-id="'+e(r.id)+'"')}${r.has_subscription?button('Gestisci / disdici','billing-pilot-portal','btn-outline','data-id="'+e(r.id)+'"'):r.blocks_checkout?button('Riprendi checkout','billing-pilot-resume','btn-outline','data-id="'+e(r.id)+'"'):''}</div></article>`).join('')}</section>`;}
  // Marketing assets are generated locally from the verified restaurant; no AI or external image service.
  async function marketingRPC(action,extra={}){const r=verifiedRestaurant(),uid=state.user?.id;if(!r||state.side!=='merchant')throw Error('Locale non disponibile.');const result=await sb.rpc('marketing_merchant',{p_action:action,p_restaurant:r.id,...extra});if(uid!==state.user?.id||state.side!=='merchant')throw Error('Sessione cambiata.');if(result.error)throw Error('Operazione marketing non disponibile. Riprova.');state.marketingData=result.data;return result.data;}
  async function marketingCustomer(action){const entry=marketingEntry(),uid=state.user?.id;if(!uid||state.side!=='customer'||!entry)return;const result=await sb.rpc('marketing_customer',{p_action:action,p_restaurant:entry.id});if(uid!==state.user?.id||state.side!=='customer')return;if(result.error)throw Error('Verifica la tua email e che il locale sia attivo.');state.marketingCustomer={...state.marketingCustomer,...result.data};render();}
  function marketingCustomerPanel(){const entry=marketingEntry();if(!entry||entry.channel!=='flyer')return '';const d=state.marketingCustomer;return '<section class="card stack"><span class="label">GOODDINER · CHECK-IN</span><h2>'+e(d?.name||'Registra la tua presenza')+'</h2><p>Se sei al ristorante, invia la richiesta dal tuo telefono. Il personale la convaliderà senza scansionare il pass. La partecipazione è facoltativa; la visita confermata può essere recensita dal locale.</p>'+(d?.status==='confirmed'?'<p class="pill">Presenza confermata</p>':d?.status==='declined'?'<p>Richiesta rifiutata dal locale.</p>':d?.status==='pending'?'<p class="pill">In attesa di conferma del locale</p>':button('Sono qui · Registra presenza','marketing-customer-request','btn-dark btn-block'))+button('Aggiorna stato','marketing-customer-info','btn-outline btn-block')+'</section>';}
  function marketingResults(){const d=state.marketingData;if(!d)return '<p>Statistiche non caricate.</p>';const levels=[[10,'Partner'],[50,'Bronze'],[100,'Silver'],[250,'Gold'],[500,'Platinum'],[1000,'Elite']],n=Number(state.marketingPartner?.qualified??d.qualified??0),current=levels.filter(x=>n>=x[0]).pop(),next=levels.find(x=>n<x[0]);return '<div class="stats"><div class="stat"><small>Iscrizioni attribuite</small><strong>'+Number(d.registrations||0)+'</strong></div><div class="stat"><small>Invitati con visita confermata</small><strong>'+n+'</strong></div><div class="stat"><small>Presenze da locandina</small><strong>'+Number(d.confirmed_requests||0)+'</strong></div></div><p>Traguardo: <strong>'+e(current?.[1]||'Inizia il percorso')+'</strong>'+(next?' · '+(next[0]-n)+' ospiti al livello '+e(next[1]):' · Livello massimo')+'</p><p>Aperture da utenti autenticati: <strong>'+Number(d.opens||0)+'</strong> · Iscrizioni da locandina: '+Number(d.flyer_registrations||0)+' · Iscrizioni dai social: '+Number(d.social_registrations||0)+'</p><p class="small muted">Le aperture anonime non sono conteggiate. I dati provengono da inviti attribuiti e non da recensioni.</p>';}
  function marketingPending(){const d=state.marketingData;return '<section class="card stack"><h2>Richieste di presenza</h2><p>Conferma solo ospiti realmente presenti. Le richieste scadono dopo 30 minuti.</p>'+button('Aggiorna richieste','marketing-refresh','btn-outline')+((d?.pending||[]).map(q=>'<article class="item"><div class="item-main"><strong>'+e(q.nickname)+'</strong><small>'+e(date(q.requested_at))+'</small></div>'+button('Conferma','marketing-confirm','btn-dark btn-small','data-id="'+e(q.id)+'"')+button('Rifiuta','marketing-decline','btn-outline btn-small','data-id="'+e(q.id)+'"')+'</article>').join('')||'<p class="muted">Nessuna richiesta in attesa.</p>')+'</section>';}
  async function marketingImage(file,max,limit){if(!file?.size)return null;if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>15000000)throw Error('Scegli un JPEG, PNG o WebP fino a 15 MB.');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((ok,no)=>{img.onload=ok;img.onerror=no;img.src=url;});const scale=Math.min(1,max/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#F7F1E8';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);for(let q=.85;q>=.35;q-=.1){const v=canvas.toDataURL('image/jpeg',q);if(v.length<=limit)return v;}throw Error('Immagine troppo grande.');}finally{URL.revokeObjectURL(url);}}
  function marketingAssetForm(){const d=state.marketingData||{};return '<section class="card stack"><h2>Identità del ristorante</h2><p>Carica il logo e una fotografia autentica di cui possiedi i diritti.</p><form id="marketing-assets-form" class="stack"><label>Logo<input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label>'+(d.logo?'<label><input type="checkbox" name="removeLogo"> Rimuovi logo salvato</label>':'')+'<label>Fotografia<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label>'+(d.photo?'<label><input type="checkbox" name="removePhoto"> Rimuovi fotografia salvata</label>':'')+'<button type="submit" class="btn btn-dark">Salva personalizzazione</button></form></section>';}
  const marketingFormats={flyer:{w:1748,h:2480,label:'Locandina A5',physical:'148mm × 210mm'},instagram:{w:1080,h:1350,label:'Post Instagram'},facebook:{w:1200,h:1200,label:'Post Facebook'},story:{w:1080,h:1920,label:'Instagram Story'},sticker:{w:1181,h:1181,label:'Adesivo vetrina',physical:'100mm × 100mm'}};
  function merchantReferralEntry(){try{const id=new URLSearchParams(window.location.search||'').get('gd_partner');return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id||'')?id:null;}catch{return null;}}
  function merchantReferralLink(r){const u=new URL('/',window.location.origin);u.searchParams.set('gd_partner',r.id);return u.href;}
  async function partnerRPC(action='stats',extra={}){const r=verifiedRestaurant(),uid=state.user?.id;if(!r||state.side!=='merchant')throw Error('Locale non disponibile.');const res=await sb.rpc('marketing_partner',{p_action:action,p_restaurant:r.id,...extra});if(uid!==state.user?.id||state.side!=='merchant')throw Error('Sessione cambiata.');if(res.error)throw Error('Operazione partner non disponibile. Riprova.');state.marketingPartner=res.data;return res.data;}
  function partnerBadge(level){const allowed=['Aderente','Partner','Bronze','Silver','Gold','Platinum','Elite'];return '<span class="pill">'+e(allowed.includes(level)?'GoodDiner '+level:'GoodDiner Aderente')+'</span>';}
  async function rewardsLedgerRPC(action='stats',key=null){const r=verifiedRestaurant(),uid=state.user?.id;if(!r||state.side!=='merchant')throw Error('Locale non disponibile.');const x=await sb.rpc('marketing_rewards',{p_action:action,p_restaurant:r.id,p_key:key});if(uid!==state.user?.id||state.side!=='merchant')throw Error('Sessione cambiata.');if(x.error)throw Error('Premi non disponibili. Riprova.');state.partnerLedger=x.data;return x.data;}
  function partnerLedgerView(){const d=state.partnerLedger;if(!d)return '<section class="card stack"><h2>Premi e Founders</h2><p>Dati non disponibili. Aggiorna il Marketing Kit.</p></section>';const ledger=d.ledger||[],labels={requested:'In verifica',approved:'Approvato · da erogare',rejected:'Non approvato',delivered:'Erogazione registrata'};return '<section class="card stack"><span class="label">GOODDINER FOUNDERS</span><h2>'+(d.founder_number?'Founder n. '+Number(d.founder_number)+' / 100':'Programma Founders')+'</h2><p>'+(d.founder_number?'Prova iniziale di 90 giorni prevista fino al '+e(date(d.founder_trial_until))+'. Consulta la licenza nella panoramica.':'Riservato ai primi 100 locali verificati.')+'</p><p>Posti disponibili: '+Number(d.founder_remaining||0)+'</p></section><section class="card stack"><h2>Premi commerciali</h2><p>Un premio per traguardo ospiti e un mese per ogni distinto ristorante invitato con pagamento reale verificato. Le richieste non sono un saldo spendibile.</p><p class="small muted">Crediti con erogazione registrata: '+(ledger.filter(x=>x.status==='delivered'&&x.kind==='credit').reduce((s,x)=>s+Number(x.amount_cents||0),0)/100).toLocaleString('it-IT',{style:'currency',currency:'EUR'})+' · Mesi erogati: '+ledger.filter(x=>x.status==='delivered'&&x.kind==='month').length+'</p>'+(d.eligible||[]).map(x=>{const l=ledger.find(y=>y.key===x.key);return '<article class="card stack"><strong>'+e(x.label)+'</strong><p>'+e(x.kind==='month'?'Un mese di abbonamento':(Number(x.amount_cents)/100).toLocaleString('it-IT',{style:'currency',currency:'EUR'}))+'</p><p class="small muted">'+e(l?labels[l.status]||l.status:x.eligible?'Traguardo raggiunto':'Non ancora raggiunto')+'</p>'+(l?.note?'<p class="small muted">'+e(l.note)+'</p>':'')+(x.eligible&&!l?button('Richiedi premio','marketing-ledger-request','btn-outline btn-block','data-id="'+e(x.key)+'"'):'')+'</article>';}).join('')+'<p class="small muted">I pagamenti di prova non danno diritto ai premi. L’erogazione reale è verificata dall’operatore.</p></section>';}
  function marketingAdminRoute(){try{return new URLSearchParams(window.location.search||'').get('gd_marketing_admin')==='1';}catch{return false;}}
  async function marketingAdminRPC(action='list',payload={}){const uid=state.user?.id;if(!uid)throw Error('Accedi con un account operatore.');const x=await sb.rpc('marketing_rewards_operator',{p_action:action,p_payload:payload});if(uid!==state.user?.id)throw Error('Sessione cambiata.');if(x.error)throw Error('Operazione non autorizzata o dati non validi.');state.marketingAdmin=x.data;return x.data;}
  function marketingAdminView(){const d=state.marketingAdmin;if(!d)return '<section class="card stack"><h1>Gestione premi</h1><p>Accesso riservato agli operatori GoodDiner autorizzati.</p>'+button('Carica registro','marketing-admin-refresh','btn-dark')+'</section>';const note='<label>Motivazione<textarea name="note" minlength="10" maxlength="500" required></textarea></label>',live='<label><input type="checkbox" name="live" required> Ho verificato l’operazione reale in Stripe Live.</label>';return '<div class="page-head"><div><span class="label">GOODDINER STUDIO · MARKETING</span><h1>Premi e Founders</h1><p>Founder assegnati: '+Number(d.founders||0)+' / 100. Nessun pagamento viene eseguito da questa schermata.</p></div>'+button('Aggiorna','marketing-admin-refresh','btn-outline')+'</div><section class="card stack"><h2>Pagamenti dei locali invitati</h2><p>Verifica direttamente in Stripe Live pagamenti reali incassati, non sandbox, gratuiti o rimborsati.</p>'+((d.referred||[]).map(x=>'<article class="card stack"><strong>'+e(x.name)+'</strong><p>Invitato da '+e(x.inviter)+' · '+e(x.license_status||'Nessuna licenza')+'</p>'+(x.payment_verified?'<p>Pagamento verificato manualmente.</p>':'<form id="marketing-admin-payment-'+e(x.id)+'" data-id="'+e(x.id)+'" class="stack"><label>ID fattura Stripe<input name="invoice" required placeholder="in_..."></label>'+note+live+'<button type="submit" class="btn btn-dark">Registra verifica</button></form>')+'</article>').join('')||'<p>Nessun locale invitato da verificare.</p>')+'</section><section class="card stack"><h2>Registro richieste premi</h2>'+((d.rewards||[]).map(x=>'<article class="card stack"><strong>'+e(x.name)+' · '+e(x.reward_key)+'</strong><p>'+e(x.status)+' · '+e(x.kind==='month'?'Un mese':(Number(x.amount_cents)/100).toLocaleString('it-IT',{style:'currency',currency:'EUR'}))+'</p>'+(x.operator_note?'<p>'+e(x.operator_note)+'</p>':'')+(x.status==='requested'?'<form id="marketing-admin-review-'+e(x.id)+'" data-id="'+e(x.id)+'" class="stack"><label>Decisione<select name="decision"><option value="approved">Approva</option><option value="rejected">Rifiuta</option></select></label>'+note+'<button class="btn btn-dark" type="submit">Registra decisione</button></form>':x.status==='approved'?'<form id="marketing-admin-delivery-'+e(x.id)+'" data-id="'+e(x.id)+'" class="stack"><label>Riferimento Stripe Live<input name="delivery" required placeholder="cbtxn_... / cn_... / in_..."></label>'+note+live+'<button class="btn btn-dark" type="submit">Registra erogazione</button></form>':'')+'</article>').join('')||'<p>Nessun premio richiesto.</p>')+'</section>';}
  function partnerLevelProgress(d){
    if(d?.qualified==null)return '<p class="small muted">Conteggio ospiti non disponibile.</p>';
    const levels=[[10,'Partner'],[50,'Bronze'],[100,'Silver'],[250,'Gold'],[500,'Platinum'],[1000,'Elite']],n=Math.max(0,Number(d.qualified)||0),next=levels.find(([min])=>n<min),current=levels.filter(([min])=>n>=min).pop();
    return '<section class="card stack"><span class="label">IL TUO PERCORSO</span><h2>'+e(current?.[1]||'Aderente')+'</h2><p><strong>'+n+'</strong> ospiti qualificati</p>'+(next?'<progress class="gd-collection-progress" value="'+Math.min(n,next[0])+'" max="'+next[0]+'" aria-label="Progresso verso '+e(next[1])+'"></progress><p>'+Math.max(0,next[0]-n)+' ospiti al livello '+e(next[1])+'</p>':'<p>Hai raggiunto il livello massimo.</p>')+'<div class="list">'+levels.map(([min,label])=>'<div class="item"><div class="item-main"><strong>'+label+'</strong><small>'+min+' ospiti</small></div><span class="pill '+(n>=min?'':'pill-gray')+'">'+(n>=min?'Raggiunto':next?.[0]===min?'Prossimo':'Da raggiungere')+'</span></div>').join('')+'</div><p class="small muted">Contano gli invitati con visita confermata; il livello non dipende dai voti assegnati agli ospiti.</p></section>';
  }
  function partnerNetwork(){const r=verifiedRestaurant(),d=state.marketingPartner;if(!d)return '<section class="card stack"><h2>Programma partner</h2><p>Non disponibile. Aggiorna il Marketing Kit.</p></section>';return partnerLevelProgress(d)+'<section class="card stack"><span class="label">GOODDINER PARTNER</span><h2>La tua scheda pubblica</h2>'+partnerBadge(d.level)+'<p>Il riconoscimento misura la partecipazione alla rete, non la qualità del locale. Nella directory degli ospiti sono visibili solo nome, città, livello ed eventuale badge Founders.</p>'+button(d.published?'Nascondi scheda pubblica':'Pubblica scheda nella directory','marketing-partner-publish','btn-outline btn-block')+'</section><section class="card stack"><h2>Invita un altro ristoratore</h2><p>Condividi il link con un collega. Per registrarsi deve comunque avere un codice invito ufficiale monouso ed essere verificato da GoodDiner.</p><p style="overflow-wrap:anywhere" class="small muted">'+e(r.id==='preview-only-venue'?'Link disponibile per i ristoratori reali':merchantReferralLink(r))+'</p>'+(r.id==='preview-only-venue'?'':button('Copia invito ristoratore','marketing-partner-copy','btn-dark btn-block'))+'<div class="stats"><div class="stat"><small>Iscritti verificati via email</small><strong>'+Number(d.invited_merchants||0)+'</strong></div><div class="stat"><small>Locali approvati</small><strong>'+Number(d.verified_merchants||0)+'</strong></div><div class="stat"><small>Licenza attiva</small><strong>'+Number(d.active_merchants||0)+'</strong></div></div></section>'+partnerLedgerView();}
  async function openPartnerDirectory(query=''){if(!state.user||state.side!=='customer')return;const uid=state.user.id;const res=await sb.rpc('marketing_directory',{p_query:query});if(uid!==state.user?.id||state.side!=='customer')return;if(res.error)throw Error('Directory non disponibile. Riprova.');state.partnerDirectory=Array.isArray(res.data)?res.data:[];state.partnerQuery=query;setView('partner-directory');}
  function partnerDirectoryView(){return '<div class="page-head"><div><span class="label">GOODDINER · PARTNER</span><h1>Scopri i locali.</h1><p>Ristoranti verificati che hanno scelto di pubblicare la scheda.</p></div>'+button('Indietro','pass','btn-outline')+'</div><section class="card stack"><form id="partner-directory-form" class="stack"><label>Cerca per nome o città<input type="search" name="query" maxlength="100" value="'+e(state.partnerQuery||'')+'" placeholder="Es. Garda"></label><button class="btn btn-dark" type="submit">Cerca</button></form><p class="small muted">I livelli riconoscono il contributo alla community, non la qualità del cibo o del servizio.</p>'+((state.partnerDirectory||[]).map(r=>'<article class="card stack"><h2>'+e(r.name)+'</h2><p>'+e(r.city)+'</p>'+partnerBadge(r.level)+(Number(r.founder_number)>0?'<span class="pill pill-warm">Founder n. '+Number(r.founder_number)+'</span>':'')+(r.booking_available===false?'<p class="small muted">Prenotazioni online temporaneamente non disponibili</p>':r.booking_available===true?button('Prenota','booking-from-map','btn-dark btn-small','data-id="'+e(r.id)+'"'):'')+'</article>').join('')||'<p>Nessun locale pubblicato corrisponde alla ricerca.</p>')+button('Vedi locali prenotabili','booking-open','btn-outline btn-block')+'</section>';}
